import sys
input = sys.stdin.read().split()
t = int(input[0])
index = 1
result = []
for _ in range(t):
    n = int(input[index])
    q = list(map(int, input[index + 1:index + n + 1]))
    min_perm = []
    max_perm = []
    used = [False] * (n + 1)
    for i in range(n):
        for j in range(1, n + 1):
            if not used[j]:
                if j == q[i]:
                    min_perm.append(j)
                    used[j] = True
                    break
    used = [False] * (n + 1)
    for j in range(n, 0, -1):
        used[q[j - 1]] = True
    for i in range(n):
        for j in range(1, q[i] + 1):
            if not used[j]:
                max_perm.append(j)
                used[j] = True
                break
        for j in range(q[i], n + 1):
            if not used[j]:
                max_perm.append(j)

    result.extend(min_perm)
    result.append("\n")
    result.extend(max_perm)
    result.append("\n")
    index += n + 1
print(" ".join(map(str, result)).strip())
